mapper.select:
SELECT cs.* FROM compute_spec cs
JOIN physical_cluster_spec pcs ON cs.id = pcs.spec_id
WHERE pcs.physical_cluster_id = #{physicalClusterId}

mapper.update:
UPDATE workspace_pool_spec_quota SET used_quota = #{usedQuota}
WHERE workspace_id = #{workspaceId}
  AND resource_pool_id = #{resourcePoolId}
  AND spec_id = #{specId}
